#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
int main(void) {
  FILE *f = tmpfile(); if (!f) return 1;
  if (fwrite("ABCDE", 1, 5, f) != 5 || fflush(f)) return 1;
  int a = fileno(f), b = dup(a); if (b < 0) return 1;
  if (lseek(a, 0, SEEK_SET) < 0) return 1;
  char x[3] = {0}, y[3] = {0};
  if (read(a, x, 2) != 2 || read(b, y, 2) != 2) return 1;
  printf("first=%s duplicate=%s\n", x, y);
  close(b); fclose(f); return 0;
}
